-- Scanner: entrada/saída por bip não pode mais travar por "lote morto".
--
-- Contexto: o QR congela o id do lote no momento da impressão. Como `lotes`
-- é duplicado por código (mesma data vira vários ids) e os duplicados são
-- deletados depois, a FK `etiquetas_qr.lote_id` (ON DELETE SET NULL) zera o
-- vínculo da linha — mas o QR continua apontando o id antigo. Ao dar entrada,
-- o Scanner gravava esse id morto em `movimentacoes.lote_id` (FK NO ACTION) e
-- o banco rejeitava (`movimentacoes_lote_id_fkey`), travando a caixa.
--
-- Solução: resolver SEMPRE um lote VIVO pela própria etiqueta — prioriza o
-- lote_id da linha; se morto/ausente, re-vincula por código + validade (o
-- mesmo lote existe sob outro id); se ainda assim não houver, grava NULL
-- (a entrada acontece e o código do lote fica na observação).

-- ── Helper reutilizável: lote vivo a partir do UID da etiqueta ───────────────
CREATE OR REPLACE FUNCTION public.resolver_lote_etiqueta(p_uid text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
    v_row_lote uuid;
    v_codigo   text;
    v_validade date;
    v_pid      integer;
    v_result   uuid;
BEGIN
    SELECT lote_id, lote_codigo_snapshot, lote_validade_snapshot, produto_master_id
      INTO v_row_lote, v_codigo, v_validade, v_pid
      FROM public.etiquetas_qr
     WHERE uid = p_uid;

    -- 1) lote da linha, se ainda existe (caminho feliz)
    IF v_row_lote IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.lotes WHERE id = v_row_lote) THEN
        RETURN v_row_lote;
    END IF;

    -- 2) re-vincular por código + validade (+ produto) — desempata pelo mais recente
    IF v_codigo IS NOT NULL THEN
        SELECT id INTO v_result
          FROM public.lotes
         WHERE codigo = v_codigo
           AND (v_pid IS NULL OR produto_id = v_pid)
           AND (v_validade IS NULL OR data_validade = v_validade)
         ORDER BY created_at DESC
         LIMIT 1;
        IF v_result IS NOT NULL THEN
            RETURN v_result;
        END IF;

        -- fallback: só por código + produto (ignora validade)
        SELECT id INTO v_result
          FROM public.lotes
         WHERE codigo = v_codigo
           AND (v_pid IS NULL OR produto_id = v_pid)
         ORDER BY created_at DESC
         LIMIT 1;
        IF v_result IS NOT NULL THEN
            RETURN v_result;
        END IF;
    END IF;

    -- 3) nada encontrado → NULL (entrada grava sem vínculo de lote)
    RETURN NULL;
END;
$fn$;

GRANT EXECUTE ON FUNCTION public.resolver_lote_etiqueta(text) TO authenticated, anon, service_role;

-- ── RPC do Scanner: resolve lote vivo + marca duplicado ──────────────────────
CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(p_loja_id integer, p_tipo text, p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_usuario_id integer;
    v_item jsonb;
    v_id text;
    v_pid integer;
    v_uid text;
    v_lote_id uuid;
    v_qty numeric;
    v_disp numeric;
    v_interna numeric;
    v_tipo_embalagem text;
    v_embalagem_nome text;
    v_lote text;
    v_payload jsonb;
    v_bip jsonb;
    v_saldo_anterior numeric;
    v_saldo_novo numeric;
    v_motivo text;
    v_observacoes text;
    v_resultados jsonb := '[]'::jsonb;
    v_ok integer := 0;
    v_err integer := 0;
BEGIN
    BEGIN
        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
    EXCEPTION WHEN OTHERS THEN
        v_usuario_id := NULL;
    END;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
    LOOP
        v_id := v_item->>'id';
        BEGIN
            v_pid := (v_item->>'pid')::integer;
            v_uid := NULLIF(v_item->>'uid', '');
            -- lote do payload é só dica; lid malformado não pode derrubar o item
            BEGIN
                v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
            EXCEPTION WHEN OTHERS THEN
                v_lote_id := NULL;
            END;
            v_qty := (v_item->>'qty')::numeric;
            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
            v_lote := NULLIF(v_item->>'lote', '');
            v_payload := v_item->'payload';

            IF v_uid IS NOT NULL THEN
                BEGIN
                    v_bip := public.bipar_etiqueta(
                        v_uid,
                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
                        jsonb_build_object(
                            'loja_id', p_loja_id,
                            'referencia_tipo', 'scanner_lote',
                            'payload', v_payload
                        )
                    );
                EXCEPTION WHEN OTHERS THEN
                    v_bip := NULL;
                END;

                -- IDEMPOTENCIA: etiqueta ja contada nesta etapa (bip duplicado) → nao lanca de novo.
                IF v_bip IS NOT NULL AND COALESCE((v_bip->>'ok')::boolean, true) = false THEN
                    v_resultados := v_resultados || jsonb_build_object(
                        'id', v_id, 'ok', false, 'duplicado', true,
                        'erro', COALESCE(NULLIF(v_bip->>'erro',''),
                                         CASE WHEN p_tipo = 'entrada'
                                              THEN 'Esta caixa já teve entrada registrada'
                                              ELSE 'Esta caixa já teve saída registrada' END)
                    );
                    v_err := v_err + 1;
                    CONTINUE;
                END IF;

                -- QTY AUTORITATIVA: o que a caixa realmente tem.
                SELECT quantidade_disponivel, quantidade_interna
                  INTO v_disp, v_interna
                  FROM etiquetas_qr
                 WHERE uid = v_uid;
                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
            END IF;

            IF v_qty IS NULL OR v_qty <= 0 THEN
                RAISE EXCEPTION '%', CASE WHEN p_tipo='entrada'
                    THEN 'Sem quantidade para dar entrada'
                    ELSE 'Container ja vazio — nada para dar saida' END;
            END IF;

            SELECT COALESCE(quantidade_atual, 0)
              INTO v_saldo_anterior
              FROM estoque
             WHERE produto_master_id = v_pid
               AND loja_id = p_loja_id;

            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);

            IF p_tipo = 'entrada' THEN
                v_saldo_novo := v_saldo_anterior + v_qty;
            ELSE
                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
            END IF;

            -- LOTE VIVO: prioriza a linha da etiqueta; re-vincula por código/validade;
            -- senão NULL. Nunca grava id de lote inexistente (evita FK e não trava).
            IF v_uid IS NOT NULL THEN
                v_lote_id := public.resolver_lote_etiqueta(v_uid);
            END IF;
            IF v_lote_id IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote_id) THEN
                v_lote_id := NULL;
            END IF;

            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
                || ' · Lote ' || COALESCE(v_lote, '—');

            INSERT INTO movimentacoes (
                produto_master_id, tipo_movimentacao, quantidade,
                quantidade_anterior, quantidade_nova, motivo, observacoes,
                data_movimentacao, loja_id, lote_id, etiqueta_qr_uid, usuario_id
            ) VALUES (
                v_pid, p_tipo, v_qty,
                v_saldo_anterior, v_saldo_novo, v_motivo, v_observacoes,
                now(), p_loja_id, v_lote_id, v_uid, v_usuario_id
            );

            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', true);
            v_ok := v_ok + 1;

        EXCEPTION WHEN OTHERS THEN
            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', false, 'erro', SQLERRM);
            v_err := v_err + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'ok', true,
        'processados', v_ok,
        'falhas', v_err,
        'resultados', v_resultados
    );
END;
$function$;

