430	export function isDuplicateBipError(erro: string | null | undefined): boolean {
431	  if (!erro) return false;
432	  const e = erro.toLowerCase();
433	  return e.includes("bip duplicado") || e.includes("já está com status") || e.includes("ja esta com status");
434	}
435	
436	/**
437	 * Extrai o status atual da etiqueta a partir da mensagem de erro da RPC.
438	 * Formato do erro: 'Etiqueta {uid} já está com status "{status}" — ...'
439	 */
440	function extractStatusFromError(erro: string): string | null {
441	  const m = erro.match(/status\s+"([^"]+)"/i) || erro.match(/status\s+'([^']+)'/i);
442	  return m ? m[1] : null;
443	}
444	
445	/**
446	 * Mensagem user-friendly pra erros de bip por contexto (etapa atual).
447	 *
448	 * Recebe opcionalmente o objeto etiqueta retornado pela RPC pra enriquecer
449	 * a mensagem com data + responsavel quando duplicate (operador entende que
450	 * a etiqueta foi marcada em OUTRA sessao, nao a atual).
451	 */
452	export function formatBipError(
453	  erro: string | null | undefined,
454	  etapa?: "separacao" | "conferencia" | "entrada" | "saida" | "consumo" | "descarte",
455	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
456	  etiqueta?: any | null,
457	): string {
458	  const fmtData = (iso: string | null | undefined) => {
459	    if (!iso) return "";
460	    try {
461	      const d = new Date(iso);
462	      return d.toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
463	    } catch { return ""; }
464	  };
465	  const contextoDuplicate = () => {
466	    if (!etiqueta) return "";
467	    const partes: string[] = [];
468	    if (etapa === "conferencia" && etiqueta.conferida_at) {
469	      const data = fmtData(etiqueta.conferida_at);
470	      if (data) partes.push(`em ${data}`);
471	    }
472	    if (etapa === "separacao" && etiqueta.separada_at) {
473	      const data = fmtData(etiqueta.separada_at);
474	      if (data) partes.push(`em ${data}`);
475	    }
476	    return partes.length ? ` (${partes.join(" · ")})` : "";
477	  };
478	  return formatBipErrorInner(erro, etapa, contextoDuplicate());
479	}
480	
481	function formatBipErrorInner(
482	  erro: string | null | undefined,
483	  etapa?: "separacao" | "conferencia" | "entrada" | "saida" | "consumo" | "descarte",
484	  sufixo: string = "",
485	): string {
486	  if (!erro) return "Bip rejeitado";
487	  if ((erro || "").toLowerCase().includes("descartada")) return "Etiqueta foi descartada";
488	  if (isDuplicateBipError(erro)) {
489	    const statusAtual = extractStatusFromError(erro);
490	    if (statusAtual) {
491	      // Status mais avançado que a etapa = etiqueta ja passou desta fase
492	      // (ex: tentando separar uma etiqueta que ja foi conferida)
493	      const fasesAvancadas: Record<string, number> = {
494	        gerada: 0, em_separacao: 1, separada: 2, conferida: 3,
495	        em_transito: 4, recebida: 5, consumida: 6, descartada: 99,
496	      };
497	      const etapaParaStatus: Record<string, string> = {
498	        separacao: 'separada', conferencia: 'conferida', saida: 'em_transito',
499	        entrada: 'recebida', consumo: 'consumida', descarte: 'descartada',
500	      };
501	      const statusEsperado = etapa ? etapaParaStatus[etapa] : null;
502	      const niveisAvancada = statusEsperado && fasesAvancadas[statusAtual] > fasesAvancadas[statusEsperado];
503	      const niveisMesma = statusEsperado && statusAtual === statusEsperado;
504	      if (niveisAvancada) {
505	        return `Etiqueta já está em "${statusAtual}" — fase posterior à de ${etapa}. Não pode voltar.`;
506	      }
507	      if (niveisMesma) {
508	        switch (etapa) {
509	          case "separacao":   return `Esta etiqueta já foi separada${sufixo}`;
510	          case "conferencia": return `Esta etiqueta já foi conferida${sufixo}`;
511	          case "entrada":     return `Esta etiqueta já foi recebida${sufixo}`;
512	          case "saida":       return `Esta etiqueta já saiu${sufixo}`;
513	          case "consumo":     return `Esta etiqueta já foi consumida${sufixo}`;
514	          case "descarte":    return `Esta etiqueta já foi descartada${sufixo}`;
515	        }
516	      }
517	      return `Etiqueta está em "${statusAtual}" — não aceita ${etapa || 'esta operação'}.`;
518	    }
519	    // Fallback se a RPC nao incluiu status no erro
520	    switch (etapa) {
521	      case "separacao":   return `Esta etiqueta já foi separada${sufixo}`;
522	      case "conferencia": return `Esta etiqueta já foi conferida${sufixo}`;
523	      case "entrada":     return `Esta etiqueta já foi recebida${sufixo}`;
524	      case "saida":       return "Esta etiqueta já saiu";
525	      case "consumo":     return "Esta etiqueta já foi consumida";
526	      case "descarte":    return "Esta etiqueta já foi descartada";
527	      default:            return "Esta etiqueta já foi lida nesta etapa";
528	    }
529	  }
530	  return erro;
531	}
