563	export function useEtiquetaScanner({
564	  enabled,
565	  onScan,
566	  onInvalid,
567	  onDuplicate,
568	  cameraElementId = "etiqueta-qr-reader",
569	  initialMode = "bluetooth",
570	}: UseEtiquetaScannerOptions) {
571	  const [scanMode, setScanMode] = useState<ScanMode>(initialMode);
572	  const [scanBuffer, setScanBuffer] = useState("");
573	  const inputRef = useRef<HTMLInputElement>(null);
574	  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
575	  const [cameraActive, setCameraActive] = useState(false);
576	  const [cameraError, setCameraError] = useState<string | null>(null);
577	  const [cameraStarting, setCameraStarting] = useState(false);
578	  const [cameraAttempt, setCameraAttempt] = useState(0);
579	  const retryCamera = useCallback(() => setCameraAttempt((n) => n + 1), []);
580	
581	  /**
582	   * Cooldown anti-repetição por modo:
583	   * - câmera: 3000ms — BarcodeDetector detecta o mesmo QR a 60fps.
584	   *   Sem janela grande, o consumer recebe N toasts por segundo.
585	   * - bluetooth: 1200ms — leitor físico pode reenviar se o operador
586	   *   segurar o gatilho. Janela menor pois não é loop automático.
587	   */
588	  const lastScanRef = useRef<{ value: string; ts: number } | null>(null);
589	  const COOLDOWN_CAMERA_MS = 3000;
590	  const COOLDOWN_BT_MS = 1200;
591	
592	  // Refs pros callbacks e scanMode — permite handleScan (deps=[]) acessar
593	  // valores atuais sem recriar o callback a cada render.
594	  const onScanRef = useRef(onScan);
595	  const onInvalidRef = useRef(onInvalid);
596	  const onDuplicateRef = useRef(onDuplicate);
597	  const scanModeRef = useRef(scanMode);
598	  useEffect(() => {
599	    onScanRef.current = onScan;
600	    onInvalidRef.current = onInvalid;
601	    onDuplicateRef.current = onDuplicate;
602	    scanModeRef.current = scanMode;
603	  });
604	
605	  const handleScan = useCallback(async (raw: string) => {
606	    setScanBuffer("");
607	
608	    const now = Date.now();
609	    const last = lastScanRef.current;
610	    const cooldown = scanModeRef.current === "camera" ? COOLDOWN_CAMERA_MS : COOLDOWN_BT_MS;
611	    if (last && last.value === raw && now - last.ts < cooldown) {
612	      // Mesma leitura dentro da janela — silencia. Câmera detecta 60x/s,
613	      // sem cooldown longo vira spam de toast. onDuplicate só dispara uma
614	      // vez por janela (primeiro hit) via throttle abaixo.
615	      return;
616	    }
617	    lastScanRef.current = { value: raw, ts: now };
618	
619	    const payload = parseQrData(raw);
620	
621	    // Rejeita apenas se o parse falhou COMPLETAMENTE (nem uid nem pid).
622	    // QR novo contém só UID → pid="" mas uid presente: válido, deixa passar.
623	    // QR legado contém pid mas uid vazio: também válido.
624	    // Consumers checam o que precisam (uid ou pid) dentro do próprio onScan.
625	    if (!payload || (!payload.uid && !payload.pid)) {
626	      // Log explícito pra debug em campo (DevTools no tablet/mobile)
627	      // eslint-disable-next-line no-console
628	      console.warn("[useEtiquetaScanner] QR rejeitado", {
629	        raw_len: raw?.length ?? 0,
630	        raw_preview: (raw || "").slice(0, 120),
631	        parsed: payload,
632	      });
633	      // Telemetria remota — admin vê todos os erros agregados, com device info,
634	      // sem precisar pedir log manual pro operador.
635	      const isOnlyHex = /^[0-9a-f]+$/i.test((raw || "").trim());
636	      const isOddLen = (raw?.length ?? 0) % 2 === 1;
637	      wideError("scanner.qr_rejected", "QR não decodificou em payload válido", {
638	        domain: "logistica",
639	        attributes: {
640	          ...getDeviceContext(),
641	          "scan.mode": scanMode,
642	          "raw.len": String(raw?.length ?? 0),
643	          "raw.preview": (raw || "").slice(0, 200),
644	          "raw.is_only_hex": String(isOnlyHex),
645	          "raw.is_odd_len": String(isOddLen),
646	        },
647	      });
648	      // Tabela Supabase (visível em /admin/telemetria-scanner)
649	      void logScannerEvent({
650	        evento: 'qr_rejected',
651	        scan_mode: scanMode,
652	        raw_len: raw?.length ?? 0,
653	        raw_preview: (raw || "").slice(0, 400),
654	        raw_is_only_hex: isOnlyHex,
655	        raw_is_odd_len: isOddLen,
656	      });
657	      playErrorSound();
658	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
659	      onInvalidRef.current?.(raw);
660	      return;
661	    }
662	    // Sucesso — log info-level pra agregar volume e detectar regressões
663	    wideInfo("scanner.qr_scanned", "QR decodificou com sucesso", {
664	      domain: "logistica",
665	      attributes: {
666	        ...getDeviceContext(),
667	        "scan.mode": scanMode,
668	        "scan.uid": payload.uid || "(sem uid)",
669	        "scan.pid": payload.pid,
670	        "raw.len": String(raw?.length ?? 0),
671	      },
672	    });
673	    void logScannerEvent({
674	      evento: 'qr_scanned',
675	      scan_mode: scanMode,
676	      scan_uid: payload.uid || null,
677	      scan_pid: payload.pid,
678	      raw_len: raw?.length ?? 0,
679	      // Persiste raw_preview também em sucesso pra diagnóstico em campo —
680	      // muitas leituras "qr_scanned" no Android Chrome 147 vem com pid OK
681	      // mas uid perdido, e a única forma de entender o que faltou é ver o raw.
682	      raw_preview: (raw || "").slice(0, 400),
683	      raw_is_only_hex: /^[0-9a-f]+$/i.test((raw || "").trim()),
684	      raw_is_odd_len: (raw?.length ?? 0) % 2 === 1,
685	    });
686	    await onScanRef.current(payload, raw);
687	  // Refs garantem que o callback nao precisa ser recriado a cada render do
688	  // consumer (que normalmente passa onScan/onInvalid/onDuplicate inline).
689	  // Sem isso, useEffect da camera/keydown re-roda em loop e camera fica eterna.
690	  // eslint-disable-next-line react-hooks/exhaustive-deps
691	  }, []);
692	
693	  // Bluetooth: foca o input invisível e mantém foco. O input ainda é renderizado
694	  // como fallback (alguns ambientes preferem input field), mas o canal primário
695	  // é o keydown global (abaixo) — bypassa IME do Android e elimina perda por
696	  // foco/blur. Mantemos os dois rodando em paralelo: se o keydown global pegar
697	  // primeiro, o input fica vazio (eventos consumidos via preventDefault opcional).
698	  useEffect(() => {
699	    if (!enabled || scanMode !== "bluetooth") return;
700	    inputRef.current?.focus();
701	    const iv = setInterval(() => {
702	      if (document.activeElement !== inputRef.current && scanMode === "bluetooth") {
703	        inputRef.current?.focus();
704	      }
705	    }, 500);
706	    return () => clearInterval(iv);
707	  }, [enabled, scanMode]);
708	
709	  // CAPTURA GLOBAL via e.code (scancode FÍSICO) — ignora layout do teclado e
710	  // IME do Android completamente. e.key passa pelo InputMethod e em PT-BR/Android
711	  // pode virar char Latin-1 (Alt codes). e.code é o ID físico da tecla
712	  // ("Digit7", "KeyA"), independente de layout.
713	  //
714	  // Confirmado via telemetria: tablet Android com Goldsky enviava bytes 0xd7
715	  // (×), 0xa3 (£), 0xc2 (Â) — Alt codes do PT-BR. Com e.code, esses chars
716	  // viram '7', 'a', 'a' (digitação real) e o JSON parseia.
717	  useEffect(() => {
718	    if (!enabled || scanMode !== "bluetooth") return;
719	
720	    let buffer = "";
721	    let timer: ReturnType<typeof setTimeout> | null = null;
722	
723	    const flush = () => {
724	      const trimmed = buffer.trim();
725	      buffer = "";
726	      if (timer) { clearTimeout(timer); timer = null; }
727	      // Threshold mínimo do UID-only (4 chars, casa com regex em parseQrData).
728	      // Antes era 20 — bloqueava silenciosamente etiquetas no formato canônico
729	      // novo (UID 8 chars), sem console, toast ou telemetria.
730	      if (trimmed.length >= 4) void handleScan(trimmed);
731	    };
732	
733	    /** Converte scancode físico → char real, ignorando layout/IME. */
734	    const codeToChar = (code: string, shift: boolean): string | null => {
735	      // Digits (DigitN → 'N' / shift+N → símbolo). Hex usa só 0-9 sem shift.
736	      const digitMatch = /^Digit([0-9])$/.exec(code);
737	      if (digitMatch) return shift ? null : digitMatch[1];
738	      // Letras (KeyA → 'a'). Hex usa a-f.
739	      const letterMatch = /^Key([A-Z])$/.exec(code);
740	      if (letterMatch) return letterMatch[1].toLowerCase();
741	      // Outros chars de JSON / formato Momma
742	      switch (code) {
743	        case "Minus":     return "-";
744	        case "Period":    return ".";
745	        case "Comma":     return ",";
746	        case "Slash":     return "/";
747	        case "Backslash": return "\\";
748	        case "Quote":     return shift ? '"' : "'";
749	        case "Semicolon": return shift ? ":" : ";";
750	        case "BracketLeft":  return shift ? "{" : "[";
751	        case "BracketRight": return shift ? "}" : "]";
752	        case "Space":     return " ";
753	        default:          return null;
754	      }
755	    };
756	
757	    const onGlobalKeyDown = (e: KeyboardEvent) => {
758	      if (e.ctrlKey || e.metaKey || e.altKey) return;
759	
760	      // Ignora se o foco está em um input editável que NÃO é o nosso
761	      const target = e.target as HTMLElement | null;
762	      const isOurInput = target === inputRef.current;
763	      const isEditable = target && (
764	        target.tagName === "INPUT" ||
765	        target.tagName === "TEXTAREA" ||
766	        target.isContentEditable
767	      );
768	      if (isEditable && !isOurInput) return;
769	
770	      if (e.code === "Enter" || e.key === "Enter") {
771	        e.preventDefault();
772	        flush();
773	        return;
774	      }
775	
776	      const ch = codeToChar(e.code, e.shiftKey);
777	      if (ch !== null) {
778	        buffer += ch;
779	        if (timer) clearTimeout(timer);
780	        timer = setTimeout(flush, 180);
781	      }
782	    };
783	
784	    document.addEventListener("keydown", onGlobalKeyDown, true);
785	    return () => {
786	      document.removeEventListener("keydown", onGlobalKeyDown, true);
787	      if (timer) clearTimeout(timer);
788	    };
789	  }, [enabled, scanMode, handleScan]);
790	
791	  // Fila serial de transições (start/stop). Sem isso, troca rápida
792	  // Bluetooth↔Câmera ou retry dispara start/stop concorrentes na lib
793	  // html5-qrcode → erro "Cannot transition to a new state. Already under
794	  // transition.". A lib não tem fila interna; nós serializamos.
795	  const transitionLockRef = useRef<Promise<unknown>>(Promise.resolve());
796	  const queueTransition = useCallback(<T,>(fn: () => Promise<T>): Promise<T> => {
797	    const next = transitionLockRef.current.then(fn, fn);
798	    transitionLockRef.current = next.catch(() => undefined);
799	    return next;
800	  }, []);
801	
802	  // CSS da câmera — injetado uma única vez globalmente
803	  useEffect(() => {
804	    const STYLE_ID = "etiqueta-scanner-camera-css";
805	    if (document.getElementById(STYLE_ID)) return;
806	    const styleEl = document.createElement("style");
807	    styleEl.id = STYLE_ID;
808	    styleEl.textContent = `
809	      .etiqueta-scanner-video-container {
810	        position: relative !important;
811	        width: 100% !important;
812	        height: 100% !important;
813	        overflow: hidden !important;
814	        background: black !important;
815	      }
816	      .etiqueta-scanner-video-container video {
817	        width: 100% !important;
818	        height: 100% !important;
819	        object-fit: contain !important;
820	        display: block !important;
821	      }
822	      [data-html5-qrcode-region="true"] {
823	        position: relative !important;
824	        width: 100% !important;
825	        height: 100% !important;
826	        overflow: hidden !important;
827	        background: black !important;
828	      }
829	      [data-html5-qrcode-region="true"] video {
830	        width: 100% !important;
831	        height: 100% !important;
832	        object-fit: contain !important;
833	        display: block !important;
834	      }
835	      [data-html5-qrcode-region="true"] img { display: none !important; }
836	    `;
837	    document.head.appendChild(styleEl);
838	  }, []);
839	
840	  // Câmera: implementação world-class
841	  // Prioridade 1 — BarcodeDetector nativo (Chrome/Edge/Android Chrome):
842	  //   hardware-accelerated, ~10-50ms por frame, ZERO overhead de lib,
843	  //   sem state machine, sem "already under transition".
844	  // Prioridade 2 — html5-qrcode sem qrbox (frame completo):
845	  //   fallback pra Firefox/Safari/Chrome sem BarcodeDetector.
846	  useEffect(() => {
847	    if (!enabled || scanMode !== "camera") return;
848	
849	    let cancelled = false;
850	    let qrLocal: Html5Qrcode | null = null;
851	    // Cleanup do path BarcodeDetector (stream + rAF)
852	    let stopBarcodeDetector: (() => void) | null = null;
853	
854	    setCameraError(null);
855	    setCameraActive(false);
856	    setCameraStarting(true);
857	
858	    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
859	      setCameraError("Este navegador não suporta acesso à câmera. Use Chrome ou Safari atualizado.");
860	      setCameraStarting(false);
861	      return;
862	    }
863	
864	    // ── Espera elemento DOM ──────────────────────────────────────────────────
865	    const waitForElement = async (): Promise<HTMLElement | null> => {
866	      for (let i = 0; i < 20; i++) {
867	        if (cancelled) return null;
868	        const el = document.getElementById(cameraElementId);
869	        if (el) return el;
870	        await new Promise((r) => setTimeout(r, 50));
871	      }
872	      return null;
873	    };
874	
875	    // ── PATH 1: BarcodeDetector nativo (Chrome/Edge/Android Chrome 9+) ───────
876	    // Hardware-accelerated, ~10-50ms/frame, zero overhead de lib,
877	    // zero state machine — sem "already under transition" ever.
878	    // Implementação direta: getUserMedia → video → rAF loop → detect.
879	    const tryBarcodeDetector = async (): Promise<boolean> => {
880	      const BD = (window as unknown as Record<string, unknown>)["BarcodeDetector"];
881	      if (typeof BD !== "function") return false;
882	
883	      let stream: MediaStream | null = null;
884	      let rafId: number | null = null;
885	      let video: HTMLVideoElement | null = null;
886	
887	      try {
888	        stream = await navigator.mediaDevices.getUserMedia({
889	          video: {
890	            facingMode: { ideal: "environment" },
891	            width: { ideal: 1920 },
892	            height: { ideal: 1080 },
893	          },
894	          audio: false,
895	        });
896	        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return false; }
897	
898	        const el = await waitForElement();
899	        if (!el || cancelled) {
900	          stream.getTracks().forEach((t) => t.stop());
901	          return false;
902	        }
903	
904	        while (el.firstChild) el.removeChild(el.firstChild);
905	        el.classList.add("etiqueta-scanner-video-container");
906	
907	        video = document.createElement("video");
908	        video.setAttribute("playsinline", "true");
909	        video.setAttribute("muted", "true");
910	        video.setAttribute("autoplay", "true");
911	        video.style.cssText = "width:100%;height:100%;object-fit:contain;display:block;background:black;";
912	        el.appendChild(video);
913	        video.srcObject = stream;
914	        await video.play().catch(() => undefined);
915	
916	        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return false; }
917	
918	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
919	        const detector = new (BD as any)({ formats: ["qr_code"] });
920	
921	        stopBarcodeDetector = () => {
922	          if (rafId !== null) cancelAnimationFrame(rafId);
923	          stream?.getTracks().forEach((t) => t.stop());
924	          try { video?.remove(); } catch { /* ignore */ }
925	        };
926	
927	        setCameraActive(true);
928	        setCameraStarting(false);
929	
930	        let detecting = false;
931	        // Após detectar um QR, pausa o loop por 2.5s.
932	        // Sem isso o loop a 60fps re-detecta o mesmo QR ~150 vezes enquanto
933	        // o usuário mantém a câmera parada, gerando spam de processamento.
934	        let pauseUntil = 0;
935	
936	        const loop = async () => {
937	          if (cancelled) return;
938	          const now = Date.now();
939	          if (!detecting && now >= pauseUntil && video && video.readyState >= 2) {
940	            detecting = true;
941	            try {
942	              // eslint-disable-next-line @typescript-eslint/no-explicit-any
943	              const codes: any[] = await detector.detect(video);
944	              if (codes.length > 0 && codes[0]?.rawValue) {
945	                void handleScan(codes[0].rawValue);
946	                // Pausa de 2.5s após detectar qualquer código (lido ou duplicado).
947	                // Permite que o operador mova a câmera antes de tentar de novo.
948	                pauseUntil = Date.now() + 2500;
949	              }
950	            } catch { /* frame fail normal */ }
951	            detecting = false;
952	          }
953	          if (!cancelled) rafId = requestAnimationFrame(loop);
954	        };
955	        rafId = requestAnimationFrame(loop);
956	        return true;
957	
958	      } catch (err) {
959	        stream?.getTracks().forEach((t) => t.stop());
960	        try { video?.remove(); } catch { /* ignore */ }
961	        throw err;
962	      }
963	    };
964	
965	    // ── PATH 2: html5-qrcode sem qrbox (frame completo) ─────────────────────
966	    // Fallback pra Firefox, Safari, Chrome sem BarcodeDetector.
967	    // SEM qrbox = lib analisa o frame inteiro. Com qrbox ela corta a área
968	    // → se QR não está exatamente centrado = missed.
969	    const tryHtml5Qrcode = async (): Promise<boolean> => {
970	      await transitionLockRef.current.catch(() => undefined);
971	      if (cancelled) return false;
972	
973	      const el = await waitForElement();
974	      if (!el || cancelled) {
975	        if (!cancelled) setCameraError("Não foi possível inicializar o leitor.");
976	        setCameraStarting(false);
977	        return false;
978	      }
979	
980	      const makeQr = (): Html5Qrcode => {
981	        while (el.firstChild) el.removeChild(el.firstChild);
982	        el.setAttribute("data-html5-qrcode-region", "true");
983	        return new Html5Qrcode(cameraElementId, {
984	          formatsToSupport: [Html5QrcodeSupportedFormats.QR_CODE],
985	          useBarCodeDetectorIfSupported: true,
986	          verbose: false,
987	        });
988	      };
989	
990	      // Sem qrbox → frame completo
991	      const cfg = { fps: 25, disableFlip: false };
992	      const onDec = (d: string) => { void handleScan(d); };
993	      const onErr = () => { /* normal */ };
994	
995	      const attempt = async (
996	        qr: Html5Qrcode,
997	        cameraArg: string,
998	        vc: MediaTrackConstraints,
999	      ): Promise<boolean> => {
1000	        try {
1001	          await queueTransition(async () => {
1002	            if (cancelled) return;
1003	            await qr.start(cameraArg, { ...cfg, videoConstraints: vc }, onDec, onErr);
1004	          });
1005	          if (cancelled) {
1006	            await queueTransition(async () => {
1007	              try { if (qr.isScanning) await qr.stop(); qr.clear(); } catch { /* ignore */ }
1008	            });
1009	            return false;
1010	          }
1011	          qrLocal = qr;
1012	          html5QrCodeRef.current = qr;
1013	          setCameraActive(true);
1014	          setCameraStarting(false);
1015	          return true;
1016	        } catch {
1017	          try { if (qr.isScanning) await qr.stop(); } catch { /* ignore */ }
1018	          try { qr.clear(); } catch { /* ignore */ }
1019	          return false;
1020	        }
1021	      };
1022	
1023	      // Tentativa 1: facingMode
1024	      if (await attempt(
1025	        makeQr(),
1026	        "environment",
1027	        { facingMode: { ideal: "environment" }, width: { ideal: 1920 }, height: { ideal: 1080 } },
1028	      )) return true;
1029	      if (cancelled) return false;
1030	
1031	      // Tentativa 2: deviceId
1032	      let cams: Array<{ id: string; label: string }> = [];
1033	      try { cams = await Html5Qrcode.getCameras(); } catch { /* ignore */ }
1034	      if (cancelled || !cams.length) {
1035	        if (!cancelled) { setCameraError("Nenhuma câmera detectada."); setCameraStarting(false); }
1036	        return false;
1037	      }
1038	      const back = cams.find((c) => /back|rear|environment|traseira/i.test(c.label || ""));
1039	      const deviceId = (back ?? cams[0]).id;
1040	
1041	      if (await attempt(
1042	        makeQr(),
1043	        deviceId,
1044	        { deviceId: { exact: deviceId }, width: { ideal: 1920 }, height: { ideal: 1080 } },
1045	      )) return true;
1046	
1047	      if (!cancelled) { setCameraError("Câmera não suportada neste dispositivo."); setCameraStarting(false); }
1048	      return false;
1049	    };
1050	
1051	    const start = async () => {
1052	      try {
1053	        const ok = await tryBarcodeDetector();
1054	        if (ok || cancelled) return;
1055	      } catch (bdErr) {
1056	        if (cancelled) return;
1057	        const msg = String(bdErr).toLowerCase();
1058	        if (msg.includes("not allowed") || msg.includes("permission") || msg.includes("denied")) {
1059	          setCameraError(describeCameraError(bdErr));
1060	          setCameraStarting(false);
1061	          return;
1062	        }
1063	        // Outro erro → tenta fallback
1064	      }
1065	      if (!cancelled) await tryHtml5Qrcode();
1066	    };
1067	
1068	    void start();
1069	
1070	    return () => {
1071	      cancelled = true;
1072	      stopBarcodeDetector?.();
1073	      const captured = qrLocal;
1074	      void queueTransition(async () => {
1075	        if (captured) {
1076	          if (captured.isScanning) await captured.stop().catch(() => undefined);
1077	          try { captured.clear(); } catch { /* ignore */ }
1078	        }
1079	      });
1080	      setCameraActive(false);
1081	      setCameraStarting(false);
1082	    };
1083	  }, [enabled, scanMode, cameraElementId, handleScan, cameraAttempt, queueTransition]);
1084	
1085	  // Input invisível AGORA é só pra atrair o foco do scanner USB no Android
1086	  // (alguns drivers só emitem keydown se há input editável focado). NÃO
1087	  // processa onChange/onKeyDown — o canal de leitura é UNICAMENTE o keydown
1088	  // global via e.code (acima). Dois canais paralelos disparavam handleScan
1089	  // com strings diferentes (input field via IME = lixo Latin-1; scancode
1090	  // global = correto). O input field é "decorativo" agora.
1091	  const inputProps = useMemo(() => ({
1092	    ref: inputRef,
1093	    type: "text" as const,
1094	    value: "",
1095	    onChange: () => { /* ignore — keydown global é a fonte unica */ },
1096	    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => {
1097	      // Previne o input acumular o lixo do IME. Tudo é processado via keydown global.
1098	      if (e.key !== "Tab" && e.key !== "Escape") e.preventDefault();
1099	    },
1100	    className: "opacity-0 absolute top-0 left-0 w-0 h-0",
1101	    autoFocus: true,
1102	    readOnly: true,
1103	    inputMode: "none" as const,
1104	    autoComplete: "off",
1105	    autoCorrect: "off",
1106	    autoCapitalize: "off",
1107	    spellCheck: false,
1108	    "data-form-type": "other" as const,
1109	  }), []);
1110	
1111	  return {
1112	    scanMode,
1113	    setScanMode,
1114	    cameraActive,
1115	    cameraStarting,
1116	    cameraError,
1117	    retryCamera,
1118	    cameraElementId,
1119	    inputProps,
1120	    /** Para trigger manual (testes ou input visível extra). */
1121	    triggerScan: handleScan,
1122	  };
1123	}
