/**
 * @module useEtiquetaScanner
 *
 * Hook único de leitura de etiquetas QR — Bluetooth (USB scanner) + Câmera.
 * Extraído do pattern de `RequisicaoConferenciaModal` pra reuso em separação,
 * conferência e recebimento. Cada bip vira um payload tipado e dedupado.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Html5Qrcode, Html5QrcodeSupportedFormats } from "html5-qrcode";
import { wideInfo, wideError } from "@/shared/lib/telemetry/wide-events";
import { supabase } from "@/integrations/supabase/client";

/**
 * Captura device info + scanMode pra cada evento de telemetria. Permite
 * ao admin filtrar problemas por dispositivo (ex: "todos os erros vindos de
 * tablets Android com USB dongle"). Roda em runtime — userAgent muda raro.
 */
function getDeviceContext() {
  if (typeof window === "undefined") return {};
  const nav = window.navigator;
  return {
    "device.user_agent": nav?.userAgent || "unknown",
    "device.platform": nav?.platform || "unknown",
    "device.lang": nav?.language || "unknown",
    "device.viewport": `${window.innerWidth}x${window.innerHeight}`,
    "device.is_secure_context": String(window.isSecureContext ?? "unknown"),
    "device.touch": String((nav?.maxTouchPoints ?? 0) > 0),
  };
}

/**
 * Persiste evento de telemetria do scanner no Supabase pra admin ver agregado.
 * Fire-and-forget — não bloqueia o fluxo do scan se falhar.
 */
export async function logScannerEvent(payload: {
  evento: 'qr_scanned' | 'qr_rejected' | 'qr_duplicate' | 'camera_error';
  scan_mode: string;
  scan_uid?: string | null;
  scan_pid?: string | null;
  raw_len?: number | null;
  raw_preview?: string | null;
  raw_is_only_hex?: boolean | null;
  raw_is_odd_len?: boolean | null;
  erro_mensagem?: string | null;
}) {
  try {
    if (typeof window === "undefined" || typeof navigator === "undefined") return;
    const { data: { user } } = await supabase.auth.getUser();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (supabase.from("scanner_telemetry" as any) as any).insert({
      ...payload,
      usuario_id: user?.id ?? null,
      user_agent: navigator.userAgent || null,
      platform: navigator.platform || null,
      viewport: `${window.innerWidth}x${window.innerHeight}`,
      is_secure_ctx: window.isSecureContext ?? null,
      is_touch: (navigator.maxTouchPoints ?? 0) > 0,
      language: navigator.language || null,
    });
  } catch {
    // não impede fluxo do scan; falha é silenciosa
  }
}

// ── Audio ──────────────────────────────────────────────────────────────────
export function playSuccessSound() {
  try {
    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    const ctx = new Ctx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.value = 800;
    osc.type = "sine";
    gain.gain.value = 0.1;
    osc.start();
    osc.stop(ctx.currentTime + 0.15);
  } catch { /* ignore */ }
}

export function playErrorSound() {
  try {
    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    const ctx = new Ctx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.setValueAtTime(300, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
    osc.type = "square";
    gain.gain.value = 0.1;
    osc.start();
    osc.stop(ctx.currentTime + 0.3);
  } catch { /* ignore */ }
}

export function playWarningSound() {
  try {
    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    const ctx = new Ctx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.value = 500;
    osc.type = "triangle";
    gain.gain.value = 0.1;
    osc.start();
    osc.stop(ctx.currentTime + 0.25);
  } catch { /* ignore */ }
}

// ── Hex decoder + parse (anti ABNT2) ───────────────────────────────────────
function decodeHex(hex: string) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  return new TextDecoder().decode(bytes);
}

/**
 * Limpa lixo que scanners Bluetooth (especialmente em tablets Android) podem
 * inserir antes/depois do payload: replacement char (�), BOM, controles
 * ASCII, zero-width spaces, line/paragraph separators. Sem isso, um único
 * caractere inválido faz o parseQrData escolher o caminho errado e JSON.parse
 * explode com "Unexpected token �".
 */
export function sanitizeScanInput(raw: string): string {
  if (!raw) return raw;
  return raw
    // Replacement char (U+FFFD) + BOM (U+FEFF)
    .replace(/[\uFFFD\uFEFF]/g, "")
    // ASCII control codes (tab, CR, LF, ESC, NUL, etc.) — exceto espaço
    // eslint-disable-next-line no-control-regex
    .replace(/[\x00-\x08\x0B-\x1F\x7F]/g, "")
    // Invisible Unicode markers (zero-width, line/para separators, word joiner).
    // ATENÇÃO: U+2028 é terminator de linha em JS — sempre escape, nunca literal.
    .replace(/[\u200B-\u200F\u2028-\u202F\u2060-\u206F]/g, "")
    .trim();
}

export interface ScannedPayload {
  pid: string;       // produto_master_id
  lid: string;       // lote_id
  lote: string;      // codigo do lote
  val: string;       // validade
  eid: string;       // embalagem_id (legacy — catalogo de embalagens)
  emb: string;       // unidade interna (un, kg, g, l, ml, sache)
  tipo?: string;     // tipo_embalagem (caixa, saco, balde, pote, galao, etc.) — pos-padrao 13/05/2026
  qty: number;       // qty interna
  uid: string;       // UID da etiqueta — chave única
}

/**
 * Tenta decodificar hex e fazer JSON.parse. Retorna o objeto ou null.
 */
function tryHex(hex: string): Record<string, unknown> | null {
  if (hex.length < 20 || hex.length % 2 !== 0) return null;
  try {
    const parsed = JSON.parse(decodeHex(hex));
    return typeof parsed === "object" && parsed !== null ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * Aceita um objeto candidato e devolve null se não tiver `p` ou `pid`
 * (sem produto não é etiqueta Momma). Caso contrário retorna o objeto.
 */
function isMommaPayload(obj: Record<string, unknown>): boolean {
  const hasP = obj["pid"] !== undefined || obj["p"] !== undefined;
  return hasP;
}

/**
 * Parse permissivo MULTI-CAMADA — desenhado pra sobreviver a USB scanners
 * em Android tablets que ocasionalmente perdem 1 caractere ou inserem prefixo
 * desconhecido. Estratégias em ordem (a primeira que retornar JSON válido com
 * `p`/`pid` ganha):
 *
 *  1. Hex puro (formato canônico LabelPrinting.encodeHex)
 *  2. Hex com pequeno lixo no meio (>80% hex)
 *  3. JSON puro (quando câmera lê o conteúdo direto, ou usuário cola)
 *  4. ABNT2 mangled (@ -> ", > -> :, < -> ,, ; -> -)
 *  5. RECOVERY: extrair maior substring hex e tentar decodificar
 *  6. RECOVERY: hex de length impar — tentar prepend e append cada char hex
 *  7. RECOVERY: extrair primeiro JSON-like substring `{...}` do conteúdo
 *
 * O hook chama isso uma vez por leitura. Custo extra das tentativas só ocorre
 * quando o caminho feliz falha — então não impacta o uso normal.
 */
export function parseQrData(value: string): ScannedPayload | null {
  const sanitized = sanitizeScanInput(value);
  if (!sanitized) return null;
  const lower = sanitized.toLowerCase();

  const candidates: Array<() => Record<string, unknown> | null> = [
    // 0) UID puro — formato canônico atual do LabelPrinting (QR contém só
    //    o UID, dados ficam no banco). 4-32 chars alfanuméricos sem '{'.
    //    Curto e robusto contra perda de chars em scanner Android.
    () => {
      if (sanitized.includes("{")) return null;
      if (!/^[0-9a-zA-Z]{4,32}$/.test(sanitized)) return null;
      // Devolve só o UID — o consumer faz lookup em etiquetas_qr pra preencher
      // produto, lote, etc. Sem isso, o resto do parser tenta tratar como hex
      // longo e falha (length impar, chars insuficientes pra JSON).
      return { u: sanitized, p: "", l: "", c: "", n: "", q: 1 };
    },

    // 1) Hex puro (legacy — etiquetas geradas antes da mudança pra UID-only)
    () => (/^[0-9a-f]+$/.test(lower) && lower.length > 32 ? tryHex(lower) : null),

    // 2) Hex com lixo do meio (>80% hex)
    () => {
      const hexOnly = lower.replace(/[^0-9a-f]/g, "");
      if (hexOnly.length < 20 || hexOnly.length / lower.length < 0.8) return null;
      return tryHex(hexOnly);
    },

    // 3) JSON puro (câmera ou paste manual)
    () => {
      if (!sanitized.includes("{")) return null;
      try {
        const start = sanitized.indexOf("{");
        const end = sanitized.lastIndexOf("}");
        if (start < 0 || end <= start) return null;
        const json = sanitized.slice(start, end + 1);
        const parsed = JSON.parse(json);
        return typeof parsed === "object" && parsed !== null ? parsed : null;
      } catch { return null; }
    },

    // 4) ABNT2 mangled
    () => {
      try {
        let r = sanitized;
        if (!r.startsWith("{")) r = `{${r}}`;
        r = r.replace(/@/g, '"').replace(/>/g, ":").replace(/</g, ",").replace(/;/g, "-");
        const parsed = JSON.parse(r);
        return typeof parsed === "object" && parsed !== null ? parsed : null;
      } catch { return null; }
    },

    // 5) Maior substring hex (em caso de prefix/suffix de protocolo)
    () => {
      const hexRuns = lower.match(/[0-9a-f]{40,}/g);
      if (!hexRuns) return null;
      // Tenta a maior primeiro
      hexRuns.sort((a, b) => b.length - a.length);
      for (const run of hexRuns) {
        const result = tryHex(run);
        if (result) return result;
      }
      return null;
    },

    // 6) Hex impar — char perdido. Tenta prepend e append de cada hex.
    () => {
      if (lower.length % 2 !== 1) return null;
      const onlyHex = /^[0-9a-f]+$/.test(lower);
      if (!onlyHex) return null;
      const hexChars = "0123456789abcdef";
      for (const c of hexChars) {
        const fwd = tryHex(c + lower);
        if (fwd) return fwd;
        const back = tryHex(lower + c);
        if (back) return back;
      }
      return null;
    },

    // 7) Extrai primeiro JSON-like {...} de qualquer lugar do conteúdo
    () => {
      const start = sanitized.indexOf("{");
      const end = sanitized.lastIndexOf("}");
      if (start < 0 || end <= start) return null;
      try {
        const parsed = JSON.parse(sanitized.slice(start, end + 1));
        return typeof parsed === "object" && parsed !== null ? parsed : null;
      } catch { return null; }
    },

    // 8) ÚLTIMO RECURSO: hex degradado decodifica mas o JSON tá corrompido
    //    (chars perdidos / trocados — Chrome Android perde eventos em rate alto).
    //    Em vez de exigir JSON válido, EXTRAI os campos diretamente via regex
    //    do CONTEÚDO DECODIFICADO. Funciona mesmo se faltam chars no meio,
    //    se `-` virou `=`, se aspa quebrou, etc. Suficiente pra montar payload.
    () => {
      // Tenta decodificar hex (puro ou degradado) pra obter o conteúdo string
      let content = "";
      if (/^[0-9a-f]+$/.test(lower) && lower.length > 20) {
        try { content = decodeHex(lower.length % 2 === 0 ? lower : lower.slice(0, -1)); } catch { return null; }
      } else {
        const hexOnly = lower.replace(/[^0-9a-f]/g, "");
        if (hexOnly.length > 20) {
          try { content = decodeHex(hexOnly.length % 2 === 0 ? hexOnly : hexOnly.slice(0, -1)); } catch { /* ignore */ }
        }
      }
      // Se hex falhou ou não é hex, tenta o sanitized direto (caso JSON puro corrompido)
      if (!content) content = sanitized;
      if (!content) return null;

      // Extrai cada campo via regex tolerante (aceita chars não-aspas no lugar de aspas)
      // ["']?p["']?\s*:\s*["']?(VALOR)["']?
      const grabStr = (key: string): string | null => {
        const re = new RegExp(`["'\`]?${key}["'\`]?\\s*[:=]\\s*["'\`]?([^"',}\\]\\s]+?)["'\`]?(?:\\s*[,}]|$)`, "i");
        const m = re.exec(content);
        return m ? m[1] : null;
      };
      const grabNum = (key: string): number | null => {
        const re = new RegExp(`["'\`]?${key}["'\`]?\\s*[:=]\\s*(\\d+)`, "i");
        const m = re.exec(content);
        return m ? Number(m[1]) : null;
      };

      // Aceita chave longa (pid/lid/qty/emb) ou curta (p/l/q/n).
      const pid = grabStr("pid") ?? grabStr("p");
      if (!pid || !/^\d+$/.test(pid)) return null;

      const uid = grabStr("uid") ?? grabStr("u") ?? "";
      const lid = grabStr("lid") ?? grabStr("l") ?? "";
      const lote = grabStr("lote") ?? grabStr("c") ?? "";
      const emb = grabStr("emb") ?? grabStr("n") ?? "";
      const qty = grabNum("qty") ?? grabNum("q") ?? 1;

      return { pid, uid, lid, lote, emb, qty };
    },
  ];

  let raw: Record<string, unknown> | null = null;
  for (const strategy of candidates) {
    const r = strategy();
    if (r && isMommaPayload(r)) { raw = r; break; }
  }
  if (!raw) return null;

  const get = (a: string, b: string) => (raw![a] ?? raw![b] ?? "") as string | number;
  const tipoRaw = String(raw!["tipo"] ?? raw!["t"] ?? "").trim();
  return {
    pid: String(get("pid", "p")),
    lid: String(get("lid", "l")),
    lote: String(get("lote", "c")),
    val: String(get("val", "v")),
    eid: String(get("eid", "e")),
    emb: String(get("emb", "n")),
    tipo: tipoRaw || undefined,
    qty: Number(raw!["qty"] ?? raw!["q"] ?? 1),
    uid: String(get("uid", "u")),
  };
}

// ── Hook ───────────────────────────────────────────────────────────────────
export type ScanMode = "bluetooth" | "camera";

export interface UseEtiquetaScannerOptions {
  enabled: boolean;
  onScan: (payload: ScannedPayload, raw: string) => void | Promise<void>;
  onInvalid?: (raw: string) => void;
  /**
   * Chamado quando o cooldown anti-repetição barrou uma leitura idêntica.
   * Útil pra mostrar feedback "caixa já lida" sem deixar o som tocar 60x/s.
   */
  onDuplicate?: (raw: string) => void;
  cameraElementId?: string;
  initialMode?: ScanMode;
}

/**
 * Detecta se uma mensagem de erro da RPC bipar_etiqueta indica duplicata
 * — etiqueta já foi bipada NESSA ETAPA específica (separação, conferência,
 * entrada, saída).
 */
/**
 * Calcula o incremento de uma bip baseado na unidade do PEDIDO e no tipo de
 * embalagem da ETIQUETA.
 *
 * Regra universal:
 *   se pedido.unidade_medida ≈ etiqueta.tipo_embalagem  → bip soma +1
 *   senao                                                → bip soma +quantidade_interna
 *
 * Exemplos:
 *   pedido "5 caixas" + etiqueta tipo=caixa, qty=12  → +1  (1/5 caixas)
 *   pedido "60 un" + mesma etiqueta                  → +12 (12/60 unidades)
 *   pedido "10 kg" + etiqueta tipo=saco, qty=5kg     → +5  (5/10 kg)
 *   pedido "2 sacos" + mesma etiqueta                → +1  (1/2 sacos)
 *
 * O "≈" cobre variantes singular/plural (caixa/caixas, saco/sacos).
 */
// Containers FÍSICOS — operador conta cada um como UMA unidade do pedido,
// independente de quantos itens internos carregam. Bipou 1 caixa, somou +1.
// Bipou 1 saco, somou +1. Mesmo que a etiqueta diga qty_interna=40 dentro.
const CONTAINER_TYPES = new Set([
  'caixa', 'saco', 'balde', 'pote', 'galao', 'lata',
  'pacote', 'garrafa', 'tambor',
]);

export function calcularIncrementoBip(
  _unidadePedido: string | null | undefined, // mantido pra compat — nao usado na decisao
  tipoEmbalagem: string | null | undefined,
  qtdInterna: number,
): number {
  // Normaliza alias do tipo da etiqueta
  const ALIASES: Record<string, string> = {
    cx: 'caixa', caixa: 'caixa', caixas: 'caixa',
    saco: 'saco', sacos: 'saco', sc: 'saco',
    balde: 'balde', baldes: 'balde',
    pote: 'pote', potes: 'pote',
    galao: 'galao', 'galão': 'galao', galoes: 'galao', 'galões': 'galao',
    lata: 'lata', latas: 'lata',
    pacote: 'pacote', pacotes: 'pacote', pct: 'pacote',
    garrafa: 'garrafa', garrafas: 'garrafa',
    tambor: 'tambor', tambores: 'tambor',
    granel: 'granel',
  };
  const t = ALIASES[(tipoEmbalagem || '').toLowerCase().trim()] ||
            (tipoEmbalagem || '').toLowerCase().trim();

  // Container fechado → operador conta 1 por bip. Independente do que está dentro.
  // Pedido pode ser "5 caixas" ou "60 un" — quem decide é o cadastro do produto:
  // se ele quer pedir em caixa, define padrão tipo=caixa; se quer pedir em un,
  // define padrão tipo=granel ou unidade_medida='un' e a etiqueta tipo=granel.
  if (CONTAINER_TYPES.has(t)) return 1;

  // Granel ou desconhecido → soma a quantidade física que tem dentro
  return qtdInterna || 1;
}

export function isDuplicateBipError(erro: string | null | undefined): boolean {
  if (!erro) return false;
  const e = erro.toLowerCase();
  return e.includes("bip duplicado") || e.includes("já está com status") || e.includes("ja esta com status");
}

/**
 * Extrai o status atual da etiqueta a partir da mensagem de erro da RPC.
 * Formato do erro: 'Etiqueta {uid} já está com status "{status}" — ...'
 */
function extractStatusFromError(erro: string): string | null {
  const m = erro.match(/status\s+"([^"]+)"/i) || erro.match(/status\s+'([^']+)'/i);
  return m ? m[1] : null;
}

/**
 * Mensagem user-friendly pra erros de bip por contexto (etapa atual).
 *
 * Recebe opcionalmente o objeto etiqueta retornado pela RPC pra enriquecer
 * a mensagem com data + responsavel quando duplicate (operador entende que
 * a etiqueta foi marcada em OUTRA sessao, nao a atual).
 */
export function formatBipError(
  erro: string | null | undefined,
  etapa?: "separacao" | "conferencia" | "entrada" | "saida" | "consumo" | "descarte",
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  etiqueta?: any | null,
): string {
  const fmtData = (iso: string | null | undefined) => {
    if (!iso) return "";
    try {
      const d = new Date(iso);
      return d.toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
    } catch { return ""; }
  };
  const contextoDuplicate = () => {
    if (!etiqueta) return "";
    const partes: string[] = [];
    if (etapa === "conferencia" && etiqueta.conferida_at) {
      const data = fmtData(etiqueta.conferida_at);
      if (data) partes.push(`em ${data}`);
    }
    if (etapa === "separacao" && etiqueta.separada_at) {
      const data = fmtData(etiqueta.separada_at);
      if (data) partes.push(`em ${data}`);
    }
    return partes.length ? ` (${partes.join(" · ")})` : "";
  };
  return formatBipErrorInner(erro, etapa, contextoDuplicate());
}

function formatBipErrorInner(
  erro: string | null | undefined,
  etapa?: "separacao" | "conferencia" | "entrada" | "saida" | "consumo" | "descarte",
  sufixo: string = "",
): string {
  if (!erro) return "Bip rejeitado";
  if ((erro || "").toLowerCase().includes("descartada")) return "Etiqueta foi descartada";
  if (isDuplicateBipError(erro)) {
    const statusAtual = extractStatusFromError(erro);
    if (statusAtual) {
      // Status mais avançado que a etapa = etiqueta ja passou desta fase
      // (ex: tentando separar uma etiqueta que ja foi conferida)
      const fasesAvancadas: Record<string, number> = {
        gerada: 0, em_separacao: 1, separada: 2, conferida: 3,
        em_transito: 4, recebida: 5, consumida: 6, descartada: 99,
      };
      const etapaParaStatus: Record<string, string> = {
        separacao: 'separada', conferencia: 'conferida', saida: 'em_transito',
        entrada: 'recebida', consumo: 'consumida', descarte: 'descartada',
      };
      const statusEsperado = etapa ? etapaParaStatus[etapa] : null;
      const niveisAvancada = statusEsperado && fasesAvancadas[statusAtual] > fasesAvancadas[statusEsperado];
      const niveisMesma = statusEsperado && statusAtual === statusEsperado;
      if (niveisAvancada) {
        return `Etiqueta já está em "${statusAtual}" — fase posterior à de ${etapa}. Não pode voltar.`;
      }
      if (niveisMesma) {
        switch (etapa) {
          case "separacao":   return `Esta etiqueta já foi separada${sufixo}`;
          case "conferencia": return `Esta etiqueta já foi conferida${sufixo}`;
          case "entrada":     return `Esta etiqueta já foi recebida${sufixo}`;
          case "saida":       return `Esta etiqueta já saiu${sufixo}`;
          case "consumo":     return `Esta etiqueta já foi consumida${sufixo}`;
          case "descarte":    return `Esta etiqueta já foi descartada${sufixo}`;
        }
      }
      return `Etiqueta está em "${statusAtual}" — não aceita ${etapa || 'esta operação'}.`;
    }
    // Fallback se a RPC nao incluiu status no erro
    switch (etapa) {
      case "separacao":   return `Esta etiqueta já foi separada${sufixo}`;
      case "conferencia": return `Esta etiqueta já foi conferida${sufixo}`;
      case "entrada":     return `Esta etiqueta já foi recebida${sufixo}`;
      case "saida":       return "Esta etiqueta já saiu";
      case "consumo":     return "Esta etiqueta já foi consumida";
      case "descarte":    return "Esta etiqueta já foi descartada";
      default:            return "Esta etiqueta já foi lida nesta etapa";
    }
  }
  return erro;
}

/**
 * Mapeia erros nativos da câmera (DOMException, getUserMedia, html5-qrcode)
 * pra mensagens em pt-BR acionáveis pelo operador.
 */
function describeCameraError(err: unknown): string {
  if (typeof err === "string") return err;
  const e = err as { name?: string; message?: string };
  const name = e?.name || "";
  const msg = e?.message || "";
  if (name === "NotAllowedError" || /permission/i.test(msg)) {
    return "Permissão da câmera negada. Libere o acesso nas configurações do navegador.";
  }
  if (name === "NotFoundError" || /no.*camera|device not found/i.test(msg)) {
    return "Nenhuma câmera detectada neste aparelho.";
  }
  if (name === "NotReadableError" || /in use|track started/i.test(msg)) {
    return "Câmera ocupada por outro app. Feche-o e tente de novo.";
  }
  if (name === "OverconstrainedError" || /constraints/i.test(msg)) {
    return "Câmera traseira indisponível — tentando câmera frontal.";
  }
  if (name === "SecurityError" || /https|secure context/i.test(msg)) {
    return "Câmera só funciona em conexão segura (HTTPS).";
  }
  if (name === "AbortError") {
    return "Inicialização da câmera foi interrompida. Tente abrir de novo.";
  }
  return msg || "Falha desconhecida ao iniciar a câmera.";
}

export function useEtiquetaScanner({
  enabled,
  onScan,
  onInvalid,
  onDuplicate,
  cameraElementId = "etiqueta-qr-reader",
  initialMode = "bluetooth",
}: UseEtiquetaScannerOptions) {
  const [scanMode, setScanMode] = useState<ScanMode>(initialMode);
  const [scanBuffer, setScanBuffer] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const html5QrCodeRef = useRef<Html5Qrcode | null>(null);
  const [cameraActive, setCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [cameraStarting, setCameraStarting] = useState(false);
  const [cameraAttempt, setCameraAttempt] = useState(0);
  const retryCamera = useCallback(() => setCameraAttempt((n) => n + 1), []);

  /**
   * Cooldown anti-repetição por modo:
   * - câmera: 3000ms — BarcodeDetector detecta o mesmo QR a 60fps.
   *   Sem janela grande, o consumer recebe N toasts por segundo.
   * - bluetooth: 1200ms — leitor físico pode reenviar se o operador
   *   segurar o gatilho. Janela menor pois não é loop automático.
   */
  const lastScanRef = useRef<{ value: string; ts: number } | null>(null);
  const COOLDOWN_CAMERA_MS = 3000;
  const COOLDOWN_BT_MS = 1200;

  // Refs pros callbacks e scanMode — permite handleScan (deps=[]) acessar
  // valores atuais sem recriar o callback a cada render.
  const onScanRef = useRef(onScan);
  const onInvalidRef = useRef(onInvalid);
  const onDuplicateRef = useRef(onDuplicate);
  const scanModeRef = useRef(scanMode);
  useEffect(() => {
    onScanRef.current = onScan;
    onInvalidRef.current = onInvalid;
    onDuplicateRef.current = onDuplicate;
    scanModeRef.current = scanMode;
  });

  const handleScan = useCallback(async (raw: string) => {
    setScanBuffer("");

    const now = Date.now();
    const last = lastScanRef.current;
    const cooldown = scanModeRef.current === "camera" ? COOLDOWN_CAMERA_MS : COOLDOWN_BT_MS;
    if (last && last.value === raw && now - last.ts < cooldown) {
      // Mesma leitura dentro da janela — silencia. Câmera detecta 60x/s,
      // sem cooldown longo vira spam de toast. onDuplicate só dispara uma
      // vez por janela (primeiro hit) via throttle abaixo.
      return;
    }
    lastScanRef.current = { value: raw, ts: now };

    const payload = parseQrData(raw);

    // Rejeita apenas se o parse falhou COMPLETAMENTE (nem uid nem pid).
    // QR novo contém só UID → pid="" mas uid presente: válido, deixa passar.
    // QR legado contém pid mas uid vazio: também válido.
    // Consumers checam o que precisam (uid ou pid) dentro do próprio onScan.
    if (!payload || (!payload.uid && !payload.pid)) {
      // Log explícito pra debug em campo (DevTools no tablet/mobile)
      // eslint-disable-next-line no-console
      console.warn("[useEtiquetaScanner] QR rejeitado", {
        raw_len: raw?.length ?? 0,
        raw_preview: (raw || "").slice(0, 120),
        parsed: payload,
      });
      // Telemetria remota — admin vê todos os erros agregados, com device info,
      // sem precisar pedir log manual pro operador.
      const isOnlyHex = /^[0-9a-f]+$/i.test((raw || "").trim());
      const isOddLen = (raw?.length ?? 0) % 2 === 1;
      wideError("scanner.qr_rejected", "QR não decodificou em payload válido", {
        domain: "logistica",
        attributes: {
          ...getDeviceContext(),
          "scan.mode": scanMode,
          "raw.len": String(raw?.length ?? 0),
          "raw.preview": (raw || "").slice(0, 200),
          "raw.is_only_hex": String(isOnlyHex),
          "raw.is_odd_len": String(isOddLen),
        },
      });
      // Tabela Supabase (visível em /admin/telemetria-scanner)
      void logScannerEvent({
        evento: 'qr_rejected',
        scan_mode: scanMode,
        raw_len: raw?.length ?? 0,
        raw_preview: (raw || "").slice(0, 400),
        raw_is_only_hex: isOnlyHex,
        raw_is_odd_len: isOddLen,
      });
      playErrorSound();
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      onInvalidRef.current?.(raw);
      return;
    }
    // Sucesso — log info-level pra agregar volume e detectar regressões
    wideInfo("scanner.qr_scanned", "QR decodificou com sucesso", {
      domain: "logistica",
      attributes: {
        ...getDeviceContext(),
        "scan.mode": scanMode,
        "scan.uid": payload.uid || "(sem uid)",
        "scan.pid": payload.pid,
        "raw.len": String(raw?.length ?? 0),
      },
    });
    void logScannerEvent({
      evento: 'qr_scanned',
      scan_mode: scanMode,
      scan_uid: payload.uid || null,
      scan_pid: payload.pid,
      raw_len: raw?.length ?? 0,
      // Persiste raw_preview também em sucesso pra diagnóstico em campo —
      // muitas leituras "qr_scanned" no Android Chrome 147 vem com pid OK
      // mas uid perdido, e a única forma de entender o que faltou é ver o raw.
      raw_preview: (raw || "").slice(0, 400),
      raw_is_only_hex: /^[0-9a-f]+$/i.test((raw || "").trim()),
      raw_is_odd_len: (raw?.length ?? 0) % 2 === 1,
    });
    await onScanRef.current(payload, raw);
  // Refs garantem que o callback nao precisa ser recriado a cada render do
  // consumer (que normalmente passa onScan/onInvalid/onDuplicate inline).
  // Sem isso, useEffect da camera/keydown re-roda em loop e camera fica eterna.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Bluetooth: foca o input invisível e mantém foco. O input ainda é renderizado
  // como fallback (alguns ambientes preferem input field), mas o canal primário
  // é o keydown global (abaixo) — bypassa IME do Android e elimina perda por
  // foco/blur. Mantemos os dois rodando em paralelo: se o keydown global pegar
  // primeiro, o input fica vazio (eventos consumidos via preventDefault opcional).
  useEffect(() => {
    if (!enabled || scanMode !== "bluetooth") return;
    inputRef.current?.focus();
    const iv = setInterval(() => {
      if (document.activeElement !== inputRef.current && scanMode === "bluetooth") {
        inputRef.current?.focus();
      }
    }, 500);
    return () => clearInterval(iv);
  }, [enabled, scanMode]);

  // CAPTURA GLOBAL via e.code (scancode FÍSICO) — ignora layout do teclado e
  // IME do Android completamente. e.key passa pelo InputMethod e em PT-BR/Android
  // pode virar char Latin-1 (Alt codes). e.code é o ID físico da tecla
  // ("Digit7", "KeyA"), independente de layout.
  //
  // Confirmado via telemetria: tablet Android com Goldsky enviava bytes 0xd7
  // (×), 0xa3 (£), 0xc2 (Â) — Alt codes do PT-BR. Com e.code, esses chars
  // viram '7', 'a', 'a' (digitação real) e o JSON parseia.
  useEffect(() => {
    if (!enabled || scanMode !== "bluetooth") return;

    let buffer = "";
    let timer: ReturnType<typeof setTimeout> | null = null;

    const flush = () => {
      const trimmed = buffer.trim();
      buffer = "";
      if (timer) { clearTimeout(timer); timer = null; }
      // Threshold mínimo do UID-only (4 chars, casa com regex em parseQrData).
      // Antes era 20 — bloqueava silenciosamente etiquetas no formato canônico
      // novo (UID 8 chars), sem console, toast ou telemetria.
      if (trimmed.length >= 4) void handleScan(trimmed);
    };

    /** Converte scancode físico → char real, ignorando layout/IME. */
    const codeToChar = (code: string, shift: boolean): string | null => {
      // Digits (DigitN → 'N' / shift+N → símbolo). Hex usa só 0-9 sem shift.
      const digitMatch = /^Digit([0-9])$/.exec(code);
      if (digitMatch) return shift ? null : digitMatch[1];
      // Letras (KeyA → 'a'). Hex usa a-f.
      const letterMatch = /^Key([A-Z])$/.exec(code);
      if (letterMatch) return letterMatch[1].toLowerCase();
      // Outros chars de JSON / formato Momma
      switch (code) {
        case "Minus":     return "-";
        case "Period":    return ".";
        case "Comma":     return ",";
        case "Slash":     return "/";
        case "Backslash": return "\\";
        case "Quote":     return shift ? '"' : "'";
        case "Semicolon": return shift ? ":" : ";";
        case "BracketLeft":  return shift ? "{" : "[";
        case "BracketRight": return shift ? "}" : "]";
        case "Space":     return " ";
        default:          return null;
      }
    };

    const onGlobalKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;

      // Ignora se o foco está em um input editável que NÃO é o nosso
      const target = e.target as HTMLElement | null;
      const isOurInput = target === inputRef.current;
      const isEditable = target && (
        target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.isContentEditable
      );
      if (isEditable && !isOurInput) return;

      if (e.code === "Enter" || e.key === "Enter") {
        e.preventDefault();
        flush();
        return;
      }

      const ch = codeToChar(e.code, e.shiftKey);
      if (ch !== null) {
        buffer += ch;
        if (timer) clearTimeout(timer);
        timer = setTimeout(flush, 180);
      }
    };

    document.addEventListener("keydown", onGlobalKeyDown, true);
    return () => {
      document.removeEventListener("keydown", onGlobalKeyDown, true);
      if (timer) clearTimeout(timer);
    };
  }, [enabled, scanMode, handleScan]);

  // Fila serial de transições (start/stop). Sem isso, troca rápida
  // Bluetooth↔Câmera ou retry dispara start/stop concorrentes na lib
  // html5-qrcode → erro "Cannot transition to a new state. Already under
  // transition.". A lib não tem fila interna; nós serializamos.
  const transitionLockRef = useRef<Promise<unknown>>(Promise.resolve());
  const queueTransition = useCallback(<T,>(fn: () => Promise<T>): Promise<T> => {
    const next = transitionLockRef.current.then(fn, fn);
    transitionLockRef.current = next.catch(() => undefined);
    return next;
  }, []);

  // CSS da câmera — injetado uma única vez globalmente
  useEffect(() => {
    const STYLE_ID = "etiqueta-scanner-camera-css";
    if (document.getElementById(STYLE_ID)) return;
    const styleEl = document.createElement("style");
    styleEl.id = STYLE_ID;
    styleEl.textContent = `
      .etiqueta-scanner-video-container {
        position: relative !important;
        width: 100% !important;
        height: 100% !important;
        overflow: hidden !important;
        background: black !important;
      }
      .etiqueta-scanner-video-container video {
        width: 100% !important;
        height: 100% !important;
        object-fit: contain !important;
        display: block !important;
      }
      [data-html5-qrcode-region="true"] {
        position: relative !important;
        width: 100% !important;
        height: 100% !important;
        overflow: hidden !important;
        background: black !important;
      }
      [data-html5-qrcode-region="true"] video {
        width: 100% !important;
        height: 100% !important;
        object-fit: contain !important;
        display: block !important;
      }
      [data-html5-qrcode-region="true"] img { display: none !important; }
    `;
    document.head.appendChild(styleEl);
  }, []);

  // Câmera: implementação world-class
  // Prioridade 1 — BarcodeDetector nativo (Chrome/Edge/Android Chrome):
  //   hardware-accelerated, ~10-50ms por frame, ZERO overhead de lib,
  //   sem state machine, sem "already under transition".
  // Prioridade 2 — html5-qrcode sem qrbox (frame completo):
  //   fallback pra Firefox/Safari/Chrome sem BarcodeDetector.
  useEffect(() => {
    if (!enabled || scanMode !== "camera") return;

    let cancelled = false;
    let qrLocal: Html5Qrcode | null = null;
    // Cleanup do path BarcodeDetector (stream + rAF)
    let stopBarcodeDetector: (() => void) | null = null;

    setCameraError(null);
    setCameraActive(false);
    setCameraStarting(true);

    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
      setCameraError("Este navegador não suporta acesso à câmera. Use Chrome ou Safari atualizado.");
      setCameraStarting(false);
      return;
    }

    // ── Espera elemento DOM ──────────────────────────────────────────────────
    const waitForElement = async (): Promise<HTMLElement | null> => {
      for (let i = 0; i < 20; i++) {
        if (cancelled) return null;
        const el = document.getElementById(cameraElementId);
        if (el) return el;
        await new Promise((r) => setTimeout(r, 50));
      }
      return null;
    };

    // ── PATH 1: BarcodeDetector nativo (Chrome/Edge/Android Chrome 9+) ───────
    // Hardware-accelerated, ~10-50ms/frame, zero overhead de lib,
    // zero state machine — sem "already under transition" ever.
    // Implementação direta: getUserMedia → video → rAF loop → detect.
    const tryBarcodeDetector = async (): Promise<boolean> => {
      const BD = (window as unknown as Record<string, unknown>)["BarcodeDetector"];
      if (typeof BD !== "function") return false;

      let stream: MediaStream | null = null;
      let rafId: number | null = null;
      let video: HTMLVideoElement | null = null;

      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: { ideal: "environment" },
            width: { ideal: 1920 },
            height: { ideal: 1080 },
          },
          audio: false,
        });
        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return false; }

        const el = await waitForElement();
        if (!el || cancelled) {
          stream.getTracks().forEach((t) => t.stop());
          return false;
        }

        while (el.firstChild) el.removeChild(el.firstChild);
        el.classList.add("etiqueta-scanner-video-container");

        video = document.createElement("video");
        video.setAttribute("playsinline", "true");
        video.setAttribute("muted", "true");
        video.setAttribute("autoplay", "true");
        video.style.cssText = "width:100%;height:100%;object-fit:contain;display:block;background:black;";
        el.appendChild(video);
        video.srcObject = stream;
        await video.play().catch(() => undefined);

        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return false; }

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const detector = new (BD as any)({ formats: ["qr_code"] });

        stopBarcodeDetector = () => {
          if (rafId !== null) cancelAnimationFrame(rafId);
          stream?.getTracks().forEach((t) => t.stop());
          try { video?.remove(); } catch { /* ignore */ }
        };

        setCameraActive(true);
        setCameraStarting(false);

        let detecting = false;
        // Após detectar um QR, pausa o loop por 2.5s.
        // Sem isso o loop a 60fps re-detecta o mesmo QR ~150 vezes enquanto
        // o usuário mantém a câmera parada, gerando spam de processamento.
        let pauseUntil = 0;

        const loop = async () => {
          if (cancelled) return;
          const now = Date.now();
          if (!detecting && now >= pauseUntil && video && video.readyState >= 2) {
            detecting = true;
            try {
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              const codes: any[] = await detector.detect(video);
              if (codes.length > 0 && codes[0]?.rawValue) {
                void handleScan(codes[0].rawValue);
                // Pausa de 2.5s após detectar qualquer código (lido ou duplicado).
                // Permite que o operador mova a câmera antes de tentar de novo.
                pauseUntil = Date.now() + 2500;
              }
            } catch { /* frame fail normal */ }
            detecting = false;
          }
          if (!cancelled) rafId = requestAnimationFrame(loop);
        };
        rafId = requestAnimationFrame(loop);
        return true;

      } catch (err) {
        stream?.getTracks().forEach((t) => t.stop());
        try { video?.remove(); } catch { /* ignore */ }
        throw err;
      }
    };

    // ── PATH 2: html5-qrcode sem qrbox (frame completo) ─────────────────────
    // Fallback pra Firefox, Safari, Chrome sem BarcodeDetector.
    // SEM qrbox = lib analisa o frame inteiro. Com qrbox ela corta a área
    // → se QR não está exatamente centrado = missed.
    const tryHtml5Qrcode = async (): Promise<boolean> => {
      await transitionLockRef.current.catch(() => undefined);
      if (cancelled) return false;

      const el = await waitForElement();
      if (!el || cancelled) {
        if (!cancelled) setCameraError("Não foi possível inicializar o leitor.");
        setCameraStarting(false);
        return false;
      }

      const makeQr = (): Html5Qrcode => {
        while (el.firstChild) el.removeChild(el.firstChild);
        el.setAttribute("data-html5-qrcode-region", "true");
        return new Html5Qrcode(cameraElementId, {
          formatsToSupport: [Html5QrcodeSupportedFormats.QR_CODE],
          useBarCodeDetectorIfSupported: true,
          verbose: false,
        });
      };

      // Sem qrbox → frame completo
      const cfg = { fps: 25, disableFlip: false };
      const onDec = (d: string) => { void handleScan(d); };
      const onErr = () => { /* normal */ };

      const attempt = async (
        qr: Html5Qrcode,
        cameraArg: string,
        vc: MediaTrackConstraints,
      ): Promise<boolean> => {
        try {
          await queueTransition(async () => {
            if (cancelled) return;
            await qr.start(cameraArg, { ...cfg, videoConstraints: vc }, onDec, onErr);
          });
          if (cancelled) {
            await queueTransition(async () => {
              try { if (qr.isScanning) await qr.stop(); qr.clear(); } catch { /* ignore */ }
            });
            return false;
          }
          qrLocal = qr;
          html5QrCodeRef.current = qr;
          setCameraActive(true);
          setCameraStarting(false);
          return true;
        } catch {
          try { if (qr.isScanning) await qr.stop(); } catch { /* ignore */ }
          try { qr.clear(); } catch { /* ignore */ }
          return false;
        }
      };

      // Tentativa 1: facingMode
      if (await attempt(
        makeQr(),
        "environment",
        { facingMode: { ideal: "environment" }, width: { ideal: 1920 }, height: { ideal: 1080 } },
      )) return true;
      if (cancelled) return false;

      // Tentativa 2: deviceId
      let cams: Array<{ id: string; label: string }> = [];
      try { cams = await Html5Qrcode.getCameras(); } catch { /* ignore */ }
      if (cancelled || !cams.length) {
        if (!cancelled) { setCameraError("Nenhuma câmera detectada."); setCameraStarting(false); }
        return false;
      }
      const back = cams.find((c) => /back|rear|environment|traseira/i.test(c.label || ""));
      const deviceId = (back ?? cams[0]).id;

      if (await attempt(
        makeQr(),
        deviceId,
        { deviceId: { exact: deviceId }, width: { ideal: 1920 }, height: { ideal: 1080 } },
      )) return true;

      if (!cancelled) { setCameraError("Câmera não suportada neste dispositivo."); setCameraStarting(false); }
      return false;
    };

    const start = async () => {
      try {
        const ok = await tryBarcodeDetector();
        if (ok || cancelled) return;
      } catch (bdErr) {
        if (cancelled) return;
        const msg = String(bdErr).toLowerCase();
        if (msg.includes("not allowed") || msg.includes("permission") || msg.includes("denied")) {
          setCameraError(describeCameraError(bdErr));
          setCameraStarting(false);
          return;
        }
        // Outro erro → tenta fallback
      }
      if (!cancelled) await tryHtml5Qrcode();
    };

    void start();

    return () => {
      cancelled = true;
      stopBarcodeDetector?.();
      const captured = qrLocal;
      void queueTransition(async () => {
        if (captured) {
          if (captured.isScanning) await captured.stop().catch(() => undefined);
          try { captured.clear(); } catch { /* ignore */ }
        }
      });
      setCameraActive(false);
      setCameraStarting(false);
    };
  }, [enabled, scanMode, cameraElementId, handleScan, cameraAttempt, queueTransition]);

  // Input invisível AGORA é só pra atrair o foco do scanner USB no Android
  // (alguns drivers só emitem keydown se há input editável focado). NÃO
  // processa onChange/onKeyDown — o canal de leitura é UNICAMENTE o keydown
  // global via e.code (acima). Dois canais paralelos disparavam handleScan
  // com strings diferentes (input field via IME = lixo Latin-1; scancode
  // global = correto). O input field é "decorativo" agora.
  const inputProps = useMemo(() => ({
    ref: inputRef,
    type: "text" as const,
    value: "",
    onChange: () => { /* ignore — keydown global é a fonte unica */ },
    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => {
      // Previne o input acumular o lixo do IME. Tudo é processado via keydown global.
      if (e.key !== "Tab" && e.key !== "Escape") e.preventDefault();
    },
    className: "opacity-0 absolute top-0 left-0 w-0 h-0",
    autoFocus: true,
    readOnly: true,
    inputMode: "none" as const,
    autoComplete: "off",
    autoCorrect: "off",
    autoCapitalize: "off",
    spellCheck: false,
    "data-form-type": "other" as const,
  }), []);

  return {
    scanMode,
    setScanMode,
    cameraActive,
    cameraStarting,
    cameraError,
    retryCamera,
    cameraElementId,
    inputProps,
    /** Para trigger manual (testes ou input visível extra). */
    triggerScan: handleScan,
  };
}

