37	          v_lote_uuid := public.find_or_create_lote(v_pid_int, v_lote_codigo, v_lote_validade, NULL, NULL);
38	        ELSE v_lote_uuid := NULL; END IF;
39	      END IF;
40	    END IF;
41	    INSERT INTO public.etiquetas_qr (uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna, quantidade_disponivel, consumida_inteira, produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot, loja_origem_id, loja_atual_id, status, tipo_embalagem, foi_separada, separada_at, separada_por, foi_conferida, conferida_at, conferida_por, backfilled, qr_payload)
42	    VALUES (p_uid, v_pid_int, v_lote_uuid, COALESCE(v_payload->>'emb', v_payload->>'n'), v_qty_interna, v_qty_interna, false, v_produto_nome, v_lote_codigo, v_lote_validade, NULL, v_loja_id, CASE p_etapa WHEN 'separacao' THEN 'gerada' WHEN 'conferencia' THEN 'gerada' WHEN 'entrada' THEN 'recebida' WHEN 'saida' THEN 'em_transito' WHEN 'consumo' THEN 'consumida' WHEN 'descarte' THEN 'descartada' END, COALESCE(v_payload->>'tipo', v_payload->>'t', 'caixa'), (p_etapa = 'separacao'), CASE WHEN p_etapa = 'separacao' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'separacao' THEN v_user_id ELSE NULL END, (p_etapa = 'conferencia'), CASE WHEN p_etapa = 'conferencia' THEN NOW() ELSE NULL END, CASE WHEN p_etapa = 'conferencia' THEN v_user_id ELSE NULL END, true, v_payload) RETURNING * INTO v_etiqueta;
