-- RPC unica e atomica para ajuste de lote na contagem manual.
-- Substitui o padrao racy "UPDATE estoque_lotes direto + INSERT movimentacao"
-- (que disparava o reconciliador sync_estoque_from_lotes e gerava lancamentos
-- 'sync_lote_auto' fantasma). Agora TUDO flui por movimentacoes, igual ao scanner:
--   movimentacao(motivo='contagem_caixa') -> trg_movimentacoes_sync_estoque_lotes
--   sincroniza estoque_lotes, e atualizar_estoque_e_alertas sincroniza estoque.
-- lote_id sempre VIVO ou NULL (nunca id morto -> nunca 23503).

CREATE OR REPLACE FUNCTION public.ajustar_lote_contagem(
  p_lote_id uuid,
  p_produto_master_id integer,
  p_loja_id integer,
  p_delta numeric,
  p_motivo text DEFAULT 'contagem_caixa',
  p_observacoes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_usuario_id integer;
  v_lote_id uuid := p_lote_id;
  v_anterior numeric;
  v_nova numeric;
  v_eff numeric;
  v_tipo text;
BEGIN
  IF p_produto_master_id IS NULL OR p_loja_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'produto/loja obrigatorios');
  END IF;
  IF p_delta IS NULL OR p_delta = 0 THEN
    RETURN jsonb_build_object('ok', true, 'noop', true);
  END IF;

  -- lote vivo ou NULL — defesa contra id morto
  IF v_lote_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote_id) THEN
    v_lote_id := NULL;
  END IF;

  BEGIN
    v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
  EXCEPTION WHEN OTHERS THEN
    v_usuario_id := NULL;
  END;

  -- trava o saldo agregado para calcular delta efetivo sem corrida
  SELECT COALESCE(quantidade_atual, 0) INTO v_anterior
    FROM public.estoque
   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
   FOR UPDATE;
  v_anterior := COALESCE(v_anterior, 0);

  v_nova := GREATEST(0, v_anterior + p_delta);
  v_eff := v_nova - v_anterior;
  IF v_eff = 0 THEN
    RETURN jsonb_build_object('ok', true, 'noop', true, 'saldo', v_nova);
  END IF;

  v_tipo := CASE WHEN v_eff > 0 THEN 'entrada' ELSE 'saida' END;

  INSERT INTO public.movimentacoes (
    produto_master_id, tipo_movimentacao, quantidade,
    quantidade_anterior, quantidade_nova, motivo, observacoes,
    data_movimentacao, loja_id, lote_id, usuario_id
  ) VALUES (
    p_produto_master_id, v_tipo, ABS(v_eff),
    v_anterior, v_nova, COALESCE(p_motivo, 'contagem_caixa'), p_observacoes,
    now(), p_loja_id, v_lote_id, v_usuario_id
  );

  RETURN jsonb_build_object(
    'ok', true, 'saldo_anterior', v_anterior, 'saldo', v_nova, 'lote_id', v_lote_id
  );
END;
$function$;

-- Estende o trigger de sync para reconhecer os motivos da contagem manual,
-- nao so 'scanner_lote'. Assim a baixa/ajuste de caixa na contagem mantem
-- estoque_lotes coerente pelos mesmos trilhos do scanner.
CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.motivo IS DISTINCT FROM 'scanner_lote'
     AND NEW.motivo IS DISTINCT FROM 'contagem_caixa'
     AND NEW.motivo IS DISTINCT FROM 'ajuste_lote_manual' THEN
    RETURN NEW;
  END IF;

  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
  PERFORM set_config('app.skip_lote_reconcile', '1', true);

  IF NEW.tipo_movimentacao = 'entrada' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;

  ELSIF NEW.tipo_movimentacao = 'saida' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;
  END IF;

  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
  END IF;

  RETURN NEW;
END;
$function$;

