CREATE POLICY "Qualquer um pode ver fotos de produtos" 
ON storage.objects 
FOR SELECT 
USING (bucket_id = 'produto-fotos');

CREATE POLICY "Usuários autenticados podem fazer upload de fotos de produtos" 
ON storage.objects 
FOR INSERT 
WITH CHECK (bucket_id = 'produto-fotos');

CREATE POLICY "Usuários autenticados podem atualizar fotos de produtos" 
ON storage.objects 
FOR UPDATE 
USING (bucket_id = 'produto-fotos');

CREATE POLICY "Usuários autenticados podem deletar fotos de produtos" 
ON storage.objects 
FOR DELETE 
USING (bucket_id = 'produto-fotos');

